CREATE TABLE attendance_devices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,church_id BIGINT NOT NULL REFERENCES churches(id) ON DELETE CASCADE,device_id VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,secret_hash VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,failed_attempts INTEGER NOT NULL DEFAULT 0,locked_until TIMESTAMP,last_used_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attendance_device_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,device_id VARCHAR(80),church_id BIGINT REFERENCES churches(id) ON DELETE SET NULL,member_code VARCHAR(50),outcome VARCHAR(30) NOT NULL,remote_address VARCHAR(64),occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_attendance_device_audit_device_time ON attendance_device_audit(device_id,occurred_at DESC);
CREATE INDEX idx_absence_retention ON absence_motivations(created_at);
CREATE INDEX idx_member_message_retention ON member_messages(created_at);
